// ---- Your code below ----

function placeBooking(db, booking) {
  db.transaction((tx) => {
    tx.insert('bookings', { ...booking, status: 'confirmed' });
    tx.insert('outbox', {
      id: 'evt_' + booking.id,
      topic: 'booking.confirmed',
      payload: { bookingId: booking.id, seatId: booking.seatId, amountCents: booking.amountCents },
    });
  });
}

class OutboxRelay {
  constructor({ db, publish, clock }) {
    this.db = db;
    this.publish = publish;
    this.clock = clock;
  }

  async runOnce(limit = 100) {
    let published = 0;
    for (const row of this.db.unsentOutbox(limit)) {
      try {
        await this.publish({ id: row.id, topic: row.topic, payload: row.payload });
        this.db.markSent(row.id, this.clock.now());
        published++;
      } catch (err) {
        break; // stop the batch to keep order; the next run retries from this row
      }
    }
    return published;
  }
}

