let t = 1000; const clock = { now: () => t };
const db = new InMemoryDb();
const sent = [];
let brokerDown = false; let failOn = null;
const publish = async (msg) => { if (brokerDown || failOn === msg.id) throw new Error('broker unavailable'); sent.push(msg); };
const relay = new OutboxRelay({ db, publish, clock });
const book = (n) => placeBooking(db, { id: 'b' + n, seatId: '14C-' + n, amountCents: 8900 });
book(1);
assertEqual(db.tables.bookings.length, 1);
assertEqual(db.tables.bookings[0].status, 'confirmed');
assertEqual(db.tables.outbox.length, 1, 'outbox row must be inserted in the same transaction');
const r = db.tables.outbox[0];
assertEqual([r.id, r.topic, r.payload], ['evt_b1', 'booking.confirmed', { bookingId: 'b1', seatId: '14C-1', amountCents: 8900 }]);

