const relay = new OutboxRelay({ db, publish, clock });
const book = (n) => placeBooking(db, { id: 'b' + n, seatId: '14C-' + n, amountCents: 8900 });
db.failNextCommit = true;
let threw = false;
try { book(1); } catch (e) { threw = true; }
assert(threw, 'placeBooking should let the commit error propagate');
assertEqual(db.tables.bookings.length, 0);
assertEqual(db.tables.outbox.length, 0);

